/** Verify synthetic input against the public schemas generated by the tested binary. */
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import Ajv from 'ajv';
const project = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const root = join(project, '.artifacts/codex-schema/0.162.0-alpha.2/json');
const fixture = JSON.parse(await readFile(join(project, 'tests/fixtures/codex/history.json'), 'utf8'));
const files = ['v1/InitializeParams.json', 'v1/InitializeResponse.json',
  'v2/ThreadListParams.json', 'v2/ThreadListResponse.json',
  'v2/ThreadReadParams.json', 'v2/ThreadReadResponse.json'];
const schemas = {}, hashes = {};
for (const file of files) {
  const bytes = await readFile(join(root, file));
  schemas[file] = JSON.parse(bytes.toString('utf8'));
  hashes[file] = createHash('sha256').update(bytes).digest('hex');
}
const ajv = new Ajv({ strict: false, validateFormats: false, allErrors: true });
const checks = [
  ['v1/InitializeParams.json', { clientInfo: { name: 'dsh_codex_bridge', title: 'Synthetic P2 test', version: '0.0.2' },
    capabilities: { experimentalApi: false, requestAttestation: false, explicitGatewayOauth: true } }],
  ['v1/InitializeResponse.json', { codexHome: 'C:\\fixture', userAgent: 'fixture', platformFamily: 'windows', platformOs: 'windows' }],
  ['v2/ThreadListParams.json', { sourceKinds: ['vscode', 'cli', 'exec', 'appServer', 'unknown'], archived: false,
    useStateDbOnly: true, sortKey: 'created_at', sortDirection: 'desc', limit: 25, cursor: 'opaque' }],
  ['v2/ThreadListResponse.json', { data: [{ ...fixture.thread, turns: [] }], nextCursor: null }],
  ['v2/ThreadReadParams.json', { threadId: 'fixture-thread', includeTurns: true }],
  ['v2/ThreadReadResponse.json', fixture],
];
for (const [file, sample] of checks) {
  const valid = ajv.compile(schemas[file]);
  assert(valid(sample), file + ': synthetic fixture mismatch ' + JSON.stringify(valid.errors));
}
const validateRead = ajv.compile(schemas['v2/ThreadReadResponse.json']);
const wrong = structuredClone(fixture); wrong.thread.createdAt = 'not-seconds';
assert.equal(validateRead(wrong), false, 'Schema validation negative control');
const wrongItem = structuredClone(fixture); wrongItem.thread.turns[0].items[0].type = 'unknownFixtureType';
assert.equal(validateRead(wrongItem), false, 'Item-union validation negative control');
const thread = schemas['v2/ThreadReadResponse.json'].definitions.Thread;
const turn = schemas['v2/ThreadReadResponse.json'].definitions.Turn;
assert.match(thread.properties.model.description, /not per-turn execution telemetry/);
assert.match(thread.properties.path.description, /UNSTABLE/);
assert.match(thread.properties.createdAt.description, /seconds/);
assert.match(turn.properties.startedAt.description, /seconds/);
assert.match(turn.properties.durationMs.description, /milliseconds/);
const facts = {
  binaryVersion: 'codex-cli 0.162.0-alpha.2', protocolSurface: 'non-experimental, not a stable binary release',
  allowedMethods: ['initialize', 'initialized', 'thread/list', 'thread/read'],
  experimentalApi: false, excludedMethods: ['thread/turns/list', 'thread/items/list', 'thread/resume', 'thread/start', 'turn/start'],
  timestampUnits: { threadCreatedUpdated: 'unix-seconds', turnStartedCompleted: 'unix-seconds', duration: 'milliseconds' },
  threadModel: 'latest/configured only; not per-turn execution telemetry',
  threadPath: 'unstable; excluded', unhydratedCounts: null, schemaSha256: hashes,
};
const baseline = join(project, 'docs/protocol/CODEX_SCHEMA_FACTS.json');
if (process.argv.includes('--capture')) await writeFile(baseline, JSON.stringify(facts, null, 2) + '\n');
else assert.deepEqual(JSON.parse(await readFile(baseline, 'utf8')), facts, 'Protocol/schema drift: review before updating the baseline');
console.log(JSON.stringify({ schemasValidated: files.length, syntheticChecks: checks.length, negativeControls: 2, schemaBaselineMatched: true }));
